WITH promo_sales AS ( SELECT ss.ss_promo_sk AS promo_sk, d.d_day_name, CASE WHEN d.d_weekend = 'Y' THEN 'Weekend' ELSE 'Weekday' END AS day_type, ss.ss_net_profit AS net_profit, ss.ss_net_paid_inc_tax AS net_paid_inc_tax FROM store_sales ss INNER JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk UNION ALL SELECT ws.ws_promo_sk AS promo_sk, d.d_day_name, CASE WHEN d.d_weekend = 'Y' THEN 'Weekend' ELSE 'Weekday' END AS day_type, ws.ws_net_profit AS net_profit, ws.ws_net_paid_inc_tax AS net_paid_inc_tax FROM web_sales ws INNER JOIN date_dim d ON ws.ws_sold_date_sk = d.d_date_sk ), promo_agg AS ( SELECT promo_sk, day_type, SUM(net_profit) AS total_net_profit, SUM(net_paid_inc_tax) AS total_net_paid_inc_tax, COUNT(*) AS transaction_count, CASE WHEN SUM(net_paid_inc_tax) = 0 THEN NULL ELSE SUM(net_profit) / SUM(net_paid_inc_tax) END AS profit_ratio FROM promo_sales GROUP BY promo_sk, day_type ) SELECT promo_sk, day_type, total_net_profit, total_net_paid_inc_tax, profit_ratio, transaction_count, CASE WHEN profit_ratio >= 0.5 THEN 'Excellent' WHEN profit_ratio >= 0.2 THEN 'Good' ELSE 'Poor' END AS profit_category, DENSE_RANK() OVER (PARTITION BY day_type ORDER BY profit_ratio DESC) AS profit_ratio_rank FROM promo_agg WHERE profit_ratio IS NOT NULL ORDER BY day_type, profit_ratio_rank LIMIT 10
